import os
import re
import uuid


def task_func(pattern: str, replacement: str, directory: str) -> bool:
    try:
        if not os.path.isdir(directory):
            return False

        try:
            regex = re.compile(pattern)
        except re.error:
            return False

        rename_map = {}
        target_names = set()

        try:
            with os.scandir(directory) as it:
                for entry in it:
                    if not entry.is_file():
                        continue
                    original_name = entry.name
                    new_name = regex.sub(replacement, original_name)
                    if new_name == original_name:
                        continue
                    if not new_name:
                        return False
                    if os.path.isabs(new_name):
                        return False
                    if os.sep and os.sep in new_name:
                        return False
                    if os.altsep and os.altsep in new_name:
                        return False
                    if new_name in target_names:
                        return False
                    target_names.add(new_name)
                    rename_map[original_name] = new_name
        except OSError:
            return False

        if not rename_map:
            return True

        source_names = set(rename_map.keys())

        for target_name in target_names:
            target_path = os.path.join(directory, target_name)
            if os.path.exists(target_path) and target_name not in source_names:
                return False

        temp_map = {}
        temp_renamed_sources = []

        try:
            for source_name in rename_map:
                source_path = os.path.join(directory, source_name)
                while True:
                    temp_name = f"__rename_tmp__{uuid.uuid4().hex}"
                    temp_path = os.path.join(directory, temp_name)
                    if not os.path.exists(temp_path):
                        break
                os.rename(source_path, temp_path)
                temp_map[source_name] = temp_name
                temp_renamed_sources.append(source_name)
        except Exception:
            for source_name in reversed(temp_renamed_sources):
                temp_name = temp_map.get(source_name)
                if temp_name is None:
                    continue
                temp_path = os.path.join(directory, temp_name)
                source_path = os.path.join(directory, source_name)
                try:
                    if os.path.exists(temp_path) and not os.path.exists(source_path):
                        os.rename(temp_path, source_path)
                except Exception:
                    pass
            return False

        finalized = []
        try:
            for source_name, target_name in rename_map.items():
                temp_name = temp_map[source_name]
                temp_path = os.path.join(directory, temp_name)
                target_path = os.path.join(directory, target_name)
                os.rename(temp_path, target_path)
                finalized.append((source_name, target_name, temp_name))
        except Exception:
            for source_name, target_name, temp_name in reversed(finalized):
                target_path = os.path.join(directory, target_name)
                temp_path = os.path.join(directory, temp_name)
                try:
                    if os.path.exists(target_path) and not os.path.exists(temp_path):
                        os.rename(target_path, temp_path)
                except Exception:
                    pass

            for source_name in reversed(list(rename_map.keys())):
                temp_name = temp_map[source_name]
                temp_path = os.path.join(directory, temp_name)
                source_path = os.path.join(directory, source_name)
                try:
                    if os.path.exists(temp_path) and not os.path.exists(source_path):
                        os.rename(temp_path, source_path)
                except Exception:
                    pass

            return False

        return True

    except Exception:
        return False
